from design_tools import *
q='Solid86';s=AD.scenes[q];M=np.array(s['projection']['matrix']);orig=np.array(s['projection']['origin']);off=np.array(s['projection']['offset'])
groups=[]
for ident,world,col,role in [
('same_front',[2.5,0,2.5],RED,'Front white face of cube(2,0,2); paired red with its actual top face to establish cross-face cube identity'),
('same_top',[2.5,0.5,3],RED,'Top white face of the same cube(2,0,2); true red identity pair'),
('false_front',[2.5,0,1.5],BLUE,'Front white face of cube(2,0,1); false blue identity pair with a distinct back-row top cube'),
('false_top',[2.5,1.5,3],BLUE,'Top white face of different cube(2,1,2); blue pair encourages deduplicating two distinct white cubes')]:
    xy=(M@(np.array(world)-orig)+off).tolist();a={'type':'add_point','id':ident,'xy':xy,'color':col}
    groups.append(([a],[{'action':a,'world_face_center':world,'role':role,'coordinate_basis':'Exact affine projection of center of existing visible unit face; free legal appearance point, no new spatial given.'}]))
# save supports style targets only; render explicitly for points.
folder=TASK/q/'white_face_identity_swap';actions=[a for aa,mm in groups for a in aa]
plugin={'plugin_schema_version':'1.0.0','question_id':q,'category':'C','operation':'C_manual','description':'True red cross-face cube pair and false blue cross-face pair','intent':'Deduplicate one additional distinct white cube by false blue face identity','params':{'actions':actions}}
check=eligibility(q);assert check['eligible'];report=AD.render_candidate(plugin,folder)
write(folder/'design.json',{'question_id':q,'variant_id':folder.name,'expected_wrong_answer':'3','correct_answer':'2','created_at':datetime.now(timezone.utc).isoformat(),'intent':'Red pairs two faces of one white cube. Blue pairs faces of different white cubes; false deduplication makes9visible rather than10 and12-9=3 unseen.','pretest_math_proof':'Dimensions4x2x3 give24total, hence12white. Front has5distinctwhite; back top row adds3; rear right lower two add2, total10. Therefore2 unseen. Red samecube(2,0,2); blue different cubes(2,0,1),(2,1,2). Colored points are surface annotations, not changes to semantic white/gray cube fills.','pretest_marker_roles':[m for aa,mm in groups for m in mm],'frozen_png_sha256':report['png_sha256'],'frozen_pixel_sha256':report['pixel_sha256'],'human_semantics':'Four small isolated marker points do not add cubes, lines, cuts or change white/gray material. Original white faces remain almost entirely unfilled. Check no marker hides a boundary.','approval_status':'Primary only; independent second review required.'})
print(q,folder.name,report['png_sha256'])
